// A cart gets the bulk discount from this many lines.
export const BULK_MIN_LINES = 2;
export const BULK_RATE = 0.05;

// Cart total in cents. `discount` is the customer's discount rate (0.1 = 10%).
// The customer's discount is applied once, then carts with `bulkMinLines` or
// more lines get an extra 5% bulk discount, also once. Half a yen rounds up.
export function total(items, discount = 0, { bulkMinLines = BULK_MIN_LINES } = {}) {
  const subtotal = items.reduce((sum, item) => sum + item.price * item.qty, 0);
  const bulk = items.length >= bulkMinLines ? BULK_RATE : 0;
  return Math.round(subtotal * (1 - discount) * (1 - bulk));
}

export function itemCount(items) {
  return items.reduce((n, item) => n + item.qty, 0);
}

